<?php
require_once __DIR__ . '/../../config.php'; require_once __DIR__ . '/../../includes/auth.php'; requireLogin();
$election_id = (int)($_GET['id'] ?? 0); $data = election_report_data($pdo, $election_id);
if (!$data) { http_response_code(404); exit('Election not found.'); }
$election = $data['election']; $isOwner = (int)$election['created_by'] === (int)$_SESSION['user_id'];
if (!(isAdmin() || $isOwner || is_active_auditor_for_election($pdo, $election_id, $_SESSION['user_id'], $_SESSION['email'] ?? ''))) { http_response_code(403); exit('You do not have access to this report.'); }
$maxHourVotes = max(array_map(fn($hour) => (int)$hour['votes'], $data['hourly_votes']) ?: [1]);
?>
<?php include __DIR__ . '/../../includes/header.php'; ?>
<div class="min-h-screen bg-gray-50 py-8"><div class="max-w-6xl mx-auto px-6">
<div class="report-titlebar"><div><p class="landing-kicker">Official election record</p><h1>Full Audit Report</h1><p><?= htmlspecialchars($election['title']) ?> &middot; Election code <strong><?= htmlspecialchars($election['code'] ?? $election['slug']) ?></strong></p></div><div class="report-downloads"><a class="app-button app-button-light" href="download-report.php?id=<?= $election_id ?>&format=pdf"><i class="bi bi-file-earmark-pdf"></i> Download PDF</a><a class="app-button app-button-primary" href="download-report.php?id=<?= $election_id ?>&format=docx"><i class="bi bi-file-earmark-word"></i> Download Word</a></div></div>
<section class="report-section"><h2>Election summary</h2><div class="report-stat-grid"><div><span>Eligible voters</span><strong><?= $data['eligible_count'] ?></strong></div><div><span>Votes cast</span><strong><?= $data['cast_count'] ?></strong></div><div><span>Voter turnout</span><strong><?= number_format($data['turnout_percent'], 1) ?>%</strong></div><div><span>Double-voting attempts</span><strong class="text-red-600"><?= $data['double_votes'] ?></strong></div><div><span>Blocked attempts</span><strong><?= $data['blocked_attempts'] ?></strong></div></div></section>
<section class="report-section"><h2>Gender distribution of participants</h2><p class="report-note">Calculated from the gender recorded on each verified voter account. “Not recorded” is retained so the total matches votes cast.</p><div class="gender-report-grid"><?php foreach (['M' => 'Male', 'F' => 'Female', 'Unknown' => 'Not recorded'] as $key => $label): $count = $data['gender'][$key]; $percent = $data['cast_count'] ? $count / $data['cast_count'] * 100 : 0; ?><div class="gender-report-item"><div><strong><?= $label ?></strong><span><?= $count ?> voter<?= $count === 1 ? '' : 's' ?> &middot; <?= number_format($percent, 1) ?>%</span></div><div class="gender-report-bar"><i style="width:<?= min(100, $percent) ?>%"></i></div></div><?php endforeach; ?></div></section>
<section class="report-section"><h2>Voting time analysis</h2><div class="time-summary"><div><span>Voting time range</span><strong><?= $data['first_vote'] ? htmlspecialchars(date('M d, Y H:i', strtotime($data['first_vote']))) . ' – ' . htmlspecialchars(date('M d, Y H:i', strtotime($data['last_vote']))) : 'No completed ballots' ?></strong></div><div><span>Most active voting hour</span><strong><?= $data['most_active'] ? htmlspecialchars(date('M d, Y H:i', strtotime($data['most_active']['hour_start']))) . ' (' . (int)$data['most_active']['votes'] . ' votes)' : 'No completed ballots' ?></strong></div></div><?php if ($data['hourly_votes']): ?><div class="vote-timeline" role="img" aria-label="Votes cast by hour"><?php foreach ($data['hourly_votes'] as $hour): $height = max(10, ((int)$hour['votes'] / $maxHourVotes) * 100); ?><div class="timeline-column" title="<?= htmlspecialchars(date('M d H:i', strtotime($hour['hour_start']))) ?>: <?= (int)$hour['votes'] ?> votes"><span><?= (int)$hour['votes'] ?></span><i style="height:<?= $height ?>%"></i><small><?= htmlspecialchars(date('M d H:i', strtotime($hour['hour_start']))) ?></small></div><?php endforeach; ?></div><?php endif; ?></section>
<section class="report-section"><h2>Candidate results</h2><?php foreach ($data['roles'] as $role): ?><div class="report-role"><h3><?= htmlspecialchars($role['role_name']) ?></h3><?php foreach ($role['candidates'] as $candidate): $pct = $role['total_votes'] ? (int)$candidate['votes'] / $role['total_votes'] * 100 : 0; ?><div class="report-candidate"><span><?= htmlspecialchars($candidate['name']) ?><?= (int)$candidate['votes'] > 0 && (int)$candidate['votes'] === $role['winner_votes'] ? ' — Winner' : '' ?></span><div><i style="width:<?= min(100, $pct) ?>%"></i></div><b><?= (int)$candidate['votes'] ?> (<?= number_format($pct, 1) ?>%)</b></div><?php endforeach; ?></div><?php endforeach; ?></section>
<section class="report-section"><h2>Double voting &amp; suspicious activity</h2><p class="report-note">There were <strong><?= $data['double_votes'] ?></strong> double-voting attempt<?= $data['double_votes'] === 1 ? '' : 's' ?> and <strong><?= $data['blocked_attempts'] ?></strong> blocked attempt<?= $data['blocked_attempts'] === 1 ? '' : 's' ?>. The table lists all blocked events.</p><div class="report-table-wrap"><table><thead><tr><th>Voter reference</th><th>Voter ID</th><th>IP address</th><th>Action</th><th>Time</th></tr></thead><tbody><?php if (!$data['blocked_events']): ?><tr><td colspan="5">No blocked attempts were logged.</td></tr><?php endif; ?><?php foreach ($data['blocked_events'] as $event): ?><tr><td><?= htmlspecialchars(anonymize_audit_reference($event['email'] ?? '') ?: '—') ?></td><td><?= htmlspecialchars(anonymize_audit_reference($event['voter_identifier'] ?? '') ?: '—') ?></td><td><?= htmlspecialchars($event['ip_address'] ?: '—') ?></td><td><?= htmlspecialchars($event['action_attempted']) ?></td><td><?= htmlspecialchars(date('M d, Y H:i', strtotime($event['attempt_time']))) ?></td></tr><?php endforeach; ?></tbody></table></div></section>
</div></div><?php include __DIR__ . '/../../includes/footer.php'; ?>
